const TAG = "mb13"

game mb13_wave

func mb13_spawn(count: number, at: location) {
    repeat count {
        spawn_mob(mob: item(husk_spawn_egg), location: at, custom_name: "mb13_mob")
        @last set_ai(ai: false)
        @last set_custom_tag(TAG, "mob")
        @last entity.set_death_drops(drops: false)
        wait(2)
    }
}

process mb13_run(at: location) {
    mb13_wave = 0
    forever {
        entity_by_conditional(has_custom_tag(TAG, "mob"))
        left = value.selection_size
        if left == 0 {
            if mb13_wave == 2 {
                @all remove_boss_bar("mb13")
                @all send_message("mb13 победа")
                return
            }
            mb13_wave += 1
            mb13_spawn(mb13_wave + 1, at)
            entity_by_conditional(has_custom_tag(TAG, "mob"))
            left = value.selection_size
            @all send_message("mb13 волна ${mb13_wave} мобов=${left}")
        }
        @all set_boss_bar("mb13", "mb13 Волна ${mb13_wave} осталось ${left}", 100, color: red)
        wait(10)
    }
}

