    all_entities()
    filter_by_conditional(entity.name_equals(value.name))
    c = value.selection_size
    @default send_message("mb15 мобы=${a} все=${b} игрок=${c}")
    entity_by_name(MOB)
    @current entity.remove()
}

when player_chat {
    if not chat_message_equals("@mb15b") {
        end_thread()
    }
    cancel_event()
    mb15_make(shift_coordinate(value.location, 3, type: x))
    entity_by_name(MOB)
    @current entity.damage(9999)
}
